/*
 * TextOverlay: a message from text/set scrolls through once (or `loops`
 * times) and hands the display back. The pictures are drawn by hand from the
 * glyphs, not generated by the code under test. '#' lit, '.' off.
 */

#include "TextOverlay.h"

#include "support/check.h"

#include <string>
#include <vector>

namespace {

constexpr uint8_t ROWS = 10;
constexpr uint8_t COLS = 11;
const RgbColor RED(255, 0, 0);

std::string picture(const std::vector<RgbColor> &frame) {
    std::string s;
    for (uint8_t r = 0; r < ROWS; r++) {
        for (uint8_t c = 0; c < COLS; c++) {
            const RgbColor &p = frame[r * COLS + c];
            s += p == RgbColor(0, 0, 0) ? '.' : (p == RED ? '#' : '?');
        }
        s += '\n';
    }
    return s;
}

std::string frameAt(TextOverlay &t, uint32_t ms) {
    std::vector<RgbColor> frame(ROWS * COLS, RgbColor(9, 9, 9));
    bool changed = false;
    t.update(ms, frame.data(), changed);
    return picture(frame);
}

void shortTextStandsCentred() {
    TextOverlay t;
    check(t.start("HI", ROWS, COLS, RED, 100, 1, 0, 0) == text::Error::None,
          "HI is accepted");
    check(t.isStatic(), "two glyphs fit 11 columns and stand still");
    check(frameAt(t, 0) == "...........\n"
                           "#...#..###.\n"
                           "#...#...#..\n"
                           "#...#...#..\n"
                           "#####...#..\n"
                           "#...#...#..\n"
                           "#...#...#..\n"
                           "#...#..###.\n"
                           "...........\n"
                           "...........\n",
          "HI fills the front from the left, one row below the top");

    TextOverlay one;
    one.start(" A ", ROWS, COLS, RED, 100, 1, 0, 0);
    check(one.length() == 1, "spaces at the ends are dropped");
    check(frameAt(one, 0) == "...........\n"
                             ".....#.....\n"
                             "....#.#....\n"
                             "...#...#...\n"
                             "...#...#...\n"
                             "...#####...\n"
                             "...#...#...\n"
                             "...#...#...\n"
                             "...........\n"
                             "...........\n",
          "one glyph stands in the middle");
}

void longTextScrollsInFromTheRight() {
    TextOverlay t;
    t.start("HIA", ROWS, COLS, RED, 100, 1, 0, 0);
    check(!t.isStatic(), "three glyphs scroll");
    check(t.width() == 17, "three glyphs are 17 columns wide");
    check(t.passMs() == (11 + 17) * 100, "one pass is front plus text wide");

    check(frameAt(t, 0) == "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n"
                           "...........\n",
          "at the start the text is just right of the front");
    check(frameAt(t, 100) == "...........\n"
                             "..........#\n"
                             "..........#\n"
                             "..........#\n"
                             "..........#\n"
                             "..........#\n"
                             "..........#\n"
                             "..........#\n"
                             "...........\n"
                             "...........\n",
          "after one step the first column of H enters on the right");
    check(frameAt(t, 1100) == "...........\n"
                              "#...#..###.\n"
                              "#...#...#..\n"
                              "#...#...#..\n"
                              "#####...#..\n"
                              "#...#...#..\n"
                              "#...#...#..\n"
                              "#...#..###.\n"
                              "...........\n"
                              "...........\n",
          "after 11 steps the text starts at the left edge");
    check(frameAt(t, 2700) == "...........\n"
                              "...........\n"
                              "...........\n"
                              "#..........\n"
                              "#..........\n"
                              "#..........\n"
                              "#..........\n"
                              "#..........\n"
                              "...........\n"
                              "...........\n",
          "in the last step only the last column of A is left");
}

void endsAfterItsLoops() {
    TextOverlay t;
    std::vector<RgbColor> frame(ROWS * COLS);
    bool changed;
    t.start("HIA", ROWS, COLS, RED, 100, 2, 0, 0);
    check(t.update(2799, frame.data(), changed), "first pass still running");
    check(t.update(2800, frame.data(), changed), "second pass begins");
    check(!t.update(5600, frame.data(), changed), "over after two passes");
    check(!t.active(), "and no longer active");

    TextOverlay endless;
    endless.start("HIA", ROWS, COLS, RED, 100, 0, 0, 0);
    check(endless.update(1000000, frame.data(), changed),
          "loops 0 runs on and on");

    TextOverlay timed;
    timed.start("HIA", ROWS, COLS, RED, 100, 0, 3, 0);
    check(timed.update(2999, frame.data(), changed), "duration not reached");
    check(!timed.update(3000, frame.data(), changed), "ends after duration");

    TextOverlay still;
    still.start("OK", ROWS, COLS, RED, 100, 1, 0, 0);
    check(still.update(2100, frame.data(), changed),
          "a standing text stays as long as a pass");
    check(!still.update(2200, frame.data(), changed),
          "and goes after (11 + 11) steps");
}

void changedOnlyPerStep() {
    TextOverlay t;
    std::vector<RgbColor> frame(ROWS * COLS);
    bool changed;
    t.start("HIA", ROWS, COLS, RED, 100, 1, 0, 0);
    t.update(0, frame.data(), changed);
    check(changed, "the first frame is drawn");
    t.update(50, frame.data(), changed);
    check(!changed, "nothing to draw within a step");
    t.update(100, frame.data(), changed);
    check(changed, "the next step is drawn");
}

void stopAndClear() {
    TextOverlay t;
    std::vector<RgbColor> frame(ROWS * COLS);
    bool changed;
    t.start("HIA", ROWS, COLS, RED, 100, 0, 0, 0);
    t.stop();
    check(t.active(), "stop() takes effect at the next update");
    check(!t.update(10, frame.data(), changed), "then the text ends");

    t.start("HIA", ROWS, COLS, RED, 100, 0, 0, 0);
    t.clear();
    check(!t.active(), "clear() ends at once");
}

void rejectsBadInput() {
    TextOverlay t;
    check(t.start("", ROWS, COLS, RED, 100, 1, 0, 0) == text::Error::Empty,
          "an empty text is rejected");
    check(t.start("   ", ROWS, COLS, RED, 100, 1, 0, 0) == text::Error::Empty,
          "only spaces is rejected");
    check(t.start(nullptr, ROWS, COLS, RED, 100, 1, 0, 0) == text::Error::Empty,
          "no text is rejected");
    std::string longText(TEXT_MAX_CHARS + 1, 'x');
    check(t.start(longText.c_str(), ROWS, COLS, RED, 100, 1, 0, 0) ==
              text::Error::TooLong,
          "more than TEXT_MAX_CHARS glyphs is rejected");
    std::string umlauts;
    for (int i = 0; i < TEXT_MAX_CHARS; i++) {
        umlauts += "\xC3\xA4";
    }
    check(t.start(umlauts.c_str(), ROWS, COLS, RED, 100, 1, 0, 0) ==
              text::Error::None,
          "the limit counts glyphs, not UTF-8 bytes");
    check(t.start("HI", 6, COLS, RED, 100, 1, 0, 0) ==
              text::Error::FrontTooSmall,
          "a front lower than the font is rejected");
    check(!t.active() || t.length() == TEXT_MAX_CHARS,
          "a rejected text leaves the running one alone");
}

void umlautsAndSpeedLimits() {
    TextOverlay t;
    t.start("\xC3\x84", ROWS, COLS, RED, 5, 1, 0, 0);
    check(frameAt(t, 0) == "...........\n"
                           "...#...#...\n"
                           ".....#.....\n"
                           "....#.#....\n"
                           "...#...#...\n"
                           "...#####...\n"
                           "...#...#...\n"
                           "...#...#...\n"
                           "...........\n"
                           "...........\n",
          "Ä shows its own glyph");
    check(t.passMs() == (11 + 5) * text::MIN_MS,
          "steps faster than MIN_MS are slowed down");
    t.start("\xC3\x84", ROWS, COLS, RED, 60000, 1, 0, 0);
    check(t.passMs() == (11 + 5) * text::MAX_MS,
          "steps slower than MAX_MS are sped up");
}

void millisWrapAround() {
    TextOverlay t;
    std::vector<RgbColor> frame(ROWS * COLS);
    bool changed;
    const uint32_t start = 0xFFFFFF00U;
    t.start("HIA", ROWS, COLS, RED, 100, 1, 0, start);
    uint32_t later = start;
    later += 1000; // wraps past zero like millis() does
    check(t.update(later, frame.data(), changed),
          "still running across the millis() wrap");
}

} // namespace

int main() {
    shortTextStandsCentred();
    longTextScrollsInFromTheRight();
    endsAfterItsLoops();
    changedOnlyPerStep();
    stopAndClear();
    rejectsBadInput();
    umlautsAndSpeedLimits();
    millisWrapAround();

    return report("text overlay");
}
